"""**Reasoning**:
I will update the `Makefile` with an idempotent `go_mod_init` target, which checks for the existence of `go.mod` before running `go mod init`. This resolves the `go.mod already exists` error encountered in the previous step.


"""

print('Updating Makefile to ensure idempotent Go module initialization...')
makefile_content = """
.PHONY: all clean build run assembly_trunk compile_xdp build_unikernel run_mesh

BIN_DIR := ./bin
GO_MODULE_NAME := keddeh_core

# --- Source Files ---
INTEGRATE_FABRIC_GO := integrate_fabric.go
COMPILE_GATEWAY_GO := compile_gateway.go
KEDDEH_XDP_C := keddeh_xdp.c
KERNEL_ENTRY_C := kernel_entry.c
KEDDEH_BOOT_S := keddeh_boot.S
LINKER_LD := linker.ld

# Placeholder Go files for various core components
MESH_CORE_GO := keddeh_core/mesh/mesh_core.go
WORKSPACE_KERNEL_GO := keddeh_core/workspace/workspace_kernel.go
BRAINK_CORE_GO := keddeh_core/braink/braink_core.go

# --- Binaries ---
KEDDEH_CORE_ENGINE := $(BIN_DIR)/keddeh_core_engine
KEDDEH_COMPILER_GATEWAY := $(BIN_DIR)/keddeh_compiler_gateway
KEDDEH_MESH_CORE := $(BIN_DIR)/keddeh_mesh_core
KEDDEH_WORKSPACE_CORE := $(BIN_DIR)/keddeh_workspace_core
KEDDEH_BRAINK_CORE := $(BIN_DIR)/keddeh_braink_core

# --- Unikernel Build Artifacts ---
KERNEL_OBJ := kernel_entry.o
BOOT_OBJ := keddeh_boot.o
KEDDEH_UNIKERNEL_BIN := $(BIN_DIR)/kernel.bin
KEDDEH_SOVEREIGN_PLATFORM_ISO := keddeh_sovereign_platform.iso

# --- eBPF Build Artifacts ---
KEDDEH_XDP_O := keddeh_xdp.o

# --- Toolchain ---
CC := gcc
AS := as
LD := ld
GRUB_MKRESCUE := grub-mkrescue
CLANG := clang
QEMU_SYSTEM_I386 := qemu-system-i386
GO := /usr/lib/go-1.18/bin/go # Explicitly define Go executable path

.PHONY: all clean build_compiler build_binaries compile_xdp build_unikernel run_mesh

all: build_compiler build_binaries compile_xdp build_unikernel

# Creates necessary directories
$(BIN_DIR):
	@mkdir -p $(BIN_DIR)

# --- Clean Targets ---
clean:
	@echo "[CLEAN] Removing build artifacts and generated files..."
	@rm -f $(KEDDEH_CORE_ENGINE) $(KEDDEH_COMPILER_GATEWAY) $(KEDDEH_MESH_CORE) $(KEDDEH_WORKSPACE_CORE) $(KEDDEH_BRAINK_CORE)
	@rm -f $(KERNEL_OBJ) $(BOOT_OBJ) $(KEDDEH_UNIKERNEL_BIN) $(KEDDEH_SOVEREIGN_PLATFORM_ISO)
	@rm -f $(KEDDEH_XDP_O)
	@rm -rf $(BIN_DIR) ./keddeh_core ./keddeh_mesh_volumes ./network_multipliers
	@rm -f go.mod go.sum
	@echo "[CLEAN] Complete."

# --- Go Modules Setup ---
go_mod_init:
	@echo "[GO_MOD] Initializing Go module $(GO_MODULE_NAME) if not exists..."
	@if [ ! -f keddeh_core/go.mod ]; then \
		cd keddeh_core && $(GO) mod init $(GO_MODULE_NAME); \
	else \
		echo "go.mod already exists in keddeh_core. Skipping go mod init."; \
	fi

go_mod_tidy:
	@echo "[GO_MOD] Tidying Go module dependencies..."
	@cd keddeh_core && $(GO) mod tidy

# --- Compilation Targets ---

# Step 1: Run integrate_fabric.go to generate main.go and engine.go in keddeh_core/
assembly_trunk:
	@echo "[ASSEMBLY_TRUNK] Running $(INTEGRATE_FABRIC_GO) to generate core Go files..."
	@$(GO) run $(INTEGRATE_FABRIC_GO)
	@$(MAKE) go_mod_init
	@$(MAKE) go_mod_tidy

# Build the compiler gateway (for demonstration purposes, if needed)
build_compiler: $(BIN_DIR) $(COMPILE_GATEWAY_GO)
	@echo "[BUILD] Compiling $(COMPILE_GATEWAY_GO)..."
	@$(GO) build -ldflags="-s -w" -o $(KEDDEH_COMPILER_GATEWAY) $(COMPILE_GATEWAY_GO)
	@echo "[BUILD] $(KEDDEH_COMPILER_GATEWAY) compilation complete."

# Build all Go binaries specified in the fabric
build_binaries: $(BIN_DIR) assembly_trunk
	@echo "[BUILD_BINARIES] Compiling keddeh_core_engine..."
	@cd keddeh_core && $(GO) build -ldflags="-s -w" -o ../$(KEDDEH_CORE_ENGINE) main.go engine.go
	@echo "[BUILD_BINARIES] Compiling keddeh_mesh_core..."
	@cd keddeh_core/mesh && $(GO) build -ldflags="-s -w" -o ../../$(KEDDEH_MESH_CORE) mesh_core.go
	@echo "[BUILD_BINARIES] Compiling keddeh_workspace_core..."
	@cd keddeh_core/workspace && $(GO) build -ldflags="-s -w" -o ../../$(KEDDEH_WORKSPACE_CORE) workspace_kernel.go
	@echo "[BUILD_BINARIES] Compiling keddeh_braink_core..."
	@cd keddeh_core/braink && $(GO) build -ldflags="-s -w" -o ../../$(KEDDEH_BRAINK_CORE) braink_core.go
	@echo "[BUILD_BINARIES] All Go binaries compiled."

# Compile eBPF Driver
compile_xdp: $(KEDDEH_XDP_C)
	@echo "[eBPF] Compiling XDP driver $(KEDDEH_XDP_C)..."
	@$(CLANG) -target bpf -O2 -emit-llvm -c $(KEDDEH_XDP_C) -o - | llc -filetype=obj -o $(KEDDEH_XDP_O)
	@echo "[eBPF] $(KEDDEH_XDP_C) compilation complete. Output: $(KEDDEH_XDP_O)"

# Build Unikernel ISO
build_unikernel: $(BIN_DIR) $(KERNEL_ENTRY_C) $(KEDDEH_BOOT_S) $(LINKER_LD)
	@echo "[UNIKERNEL] Building keddeh_sovereign_platform.iso..."
	@$(CC) -m32 -c $(KERNEL_ENTRY_C) -o $(KERNEL_OBJ) -std=gnu99 -ffreestanding -O2 -Wall -Wextra
	@$(AS) --32 $(KEDDEH_BOOT_S) -o $(BOOT_OBJ)
	@$(LD) -m elf_i386 -T $(LINKER_LD) $(BOOT_OBJ) $(KERNEL_OBJ) -o $(KEDDEH_UNIKERNEL_BIN)
	@mkdir -p iso/boot/grub
	@cp $(KEDDEH_UNIKERNEL_BIN) iso/boot/
	@echo 'set timeout=0' > iso/boot/grub/grub.cfg
	@echo 'set default=0' >> iso/boot/grub/grub.cfg
	@echo '' >> iso/boot/grub/grub.cfg
	@echo 'menuentry "keddeh_sovereign_platform" {' >> iso/boot/grub/grub.cfg
	@echo '  multiboot /boot/kernel.bin' >> iso/boot/grub/grub.cfg
	@echo '  boot' >> iso/boot/grub/grub.cfg
	@echo '}' >> iso/boot/grub/grub.cfg
	@$(GRUB_MKRESCUE) -o $(KEDDEH_SOVEREIGN_PLATFORM_ISO) iso
	@rm -rf iso $(KERNEL_OBJ) $(BOOT_OBJ)
	@echo "[UNIKERNEL] keddeh_sovereign_platform.iso created."

# --- Run Targets ---
run_compiler:
	@echo "[RUN] Running $(KEDDEH_COMPILER_GATEWAY)..."
	@$(KEDDEH_COMPILER_GATEWAY)

run_mesh:
	@echo "[RUN] Running $(KEDDEH_CORE_ENGINE)..."
	@$(KEDDEH_CORE_ENGINE)
"""
with open('Makefile', 'w') as f:
    f.write(makefile_content)
print('Makefile updated successfully with idempotent go_mod_init target.')

