# Commented out IPython magic to ensure Python compatibility.
# %%writefile Makefile
# .PHONY: all clean build run run_enterprise run_braink
# 
# APP_NAME = enterprise_routing_system
# GO_FILES = enterprise_routing_system.go matrix_address_translation_engine.go
# 
# all: build
# 
# clean:
# 	@echo "[CLEAN] Removing build artifacts..."
# 	@rm -f $(APP_NAME)
