"""### Test the `/v1/network/tunnel` Endpoint

Now that the `enterprise_routing_system` has been compiled, let's test its `/v1/network/tunnel` endpoint. We will use a Python script to send a sample `POST` request with a `SpatialNetworkFrame` payload and print the response.
"""

import requests
import json

# The endpoint URL, matching the EnterpriseControlPlaneBindingAddress in enterprise_routing_system.go
url = 'http://localhost:8080/v1/network/tunnel'
headers = {'Content-Type': 'application/json'}

# Sample payload matching the SpatialNetworkFrame structure
payload = {
    "transaction_id": "TXN-001",
    "corporate_domain_context": "example.com",
    "originating_source_row": 1,
    "originating_source_col": 1,
    "destination_target_row": 10,
    "destination_target_col": 20,
    "raw_payload_data_bytes": "SGVsbG8sIHRoaXMgaXMgYSB0ZXN0IHBheWxvYWQuICBBc2dyaWQgQmVud2FkIEVkaXRpb24u"
}

print(f"Sending POST request to {url} with payload:\n{json.dumps(payload, indent=2)}")

try:
    response = requests.post(url, headers=headers, data=json.dumps(payload))
    print(f"\nResponse Status Code: {response.status_code}")

    # Attempt to parse JSON only if the response is not empty and content type is JSON
    if response.text and 'application/json' in response.headers.get('Content-Type', ''):
        print(f"Response Body: {json.dumps(response.json(), indent=2)}")
    else:
        print(f"Raw Response Body (not JSON): {response.text}")

except requests.exceptions.ConnectionError as e:
    print(f"\nError: Could not connect to the server. Is the `enterprise_routing_system` running on port 8080? {e}")
except json.JSONDecodeError:
    print(f"\nError: Could not decode JSON response. Raw response: {response.text}")
except Exception as e:
    print(f"\nAn unexpected error occurred: {e}")

