"""## Integrate Dynamic File Browser

### Subtask:
Develop and embed a visual, interactive file browser inside the dashboard to display the file system and simulated GCS substrate contents dynamically.

**Reasoning**:
I will create a Python cell to implement the `_list_substrate_files` callback function, register it with Google Colab's interactive kernel system, and output the updated comprehensive HTML/CSS/JS dashboard featuring the dynamic interactive file browser.
"""

import os
import json
from IPython.display import HTML, display
from google.colab import output

# --- Backend File Browser Logic & Callback ---
def _list_substrate_files():
    print("[FILE BROWSER] Fetching files dynamically...")
    root_dir = "/content"
    files_structure = []

    try:
        for item in sorted(os.listdir(root_dir)):
            full_path = os.path.join(root_dir, item)
            is_dir = os.path.isdir(full_path)
            files_structure.append({
                "name": item,
                "type": "directory" if is_dir else "file",
                "size": os.path.getsize(full_path) if not is_dir else "-"
            })
    except Exception as e:
        print(f"[ERROR] Error reading storage: {str(e)}")
        return json.dumps([{"name": f"Error reading files: {str(e)}", "type": "error", "size": "-"}])

    return json.dumps(files_structure)

# Register the file browser callback globally
output.register_callback('list_substrate_files', _list_substrate_files)

