import os
import json
from IPython.display import HTML, display
from google.colab import output

# --- Backend API Callbacks ---
def _process_ai_prompt(prompt_text):
    print(f"[AI HUB] Processing prompt: {prompt_text}")
    prompt_lower = prompt_text.lower()
    if "status" in prompt_lower or "check" in prompt_lower:
        response = {
            "status": "success",
            "route": "System Diagnostics",
            "response": "All sovereign systems are operating within normal parameters. BGP active, DPDK aligned."
        }
    elif "mount" in prompt_lower or "substrate" in prompt_lower or "storage" in prompt_lower:
        response = {
            "status": "success",
            "route": "Storage Controller",
            "response": "Sovereign 100TB+ storage substrate is fully mounted and mapped to index directories."
        }
    elif "route" in prompt_lower or "bgp" in prompt_lower or "network" in prompt_lower:
        response = {
            "status": "success",
            "route": "Carrier Route Control",
            "response": "Enterprise routing table synchronized. Peer AS65001 responding with zero packet loss."
        }
    else:
        response = {
            "status": "success",
            "route": "General Intelligence Agent",
            "response": f"Processed command '{prompt_text}' under general cognitive orchestration."
        }
    return json.dumps(response)

def _trigger_sovereign_task(task_action):
    print(f"[TASK QUEUE] Triggered task: {task_action}")
    logs = []
    if task_action == "fabric_init":
        logs.append("INIT: Invoking build sequence for sovereign matrix...")
        logs.append("SUCCESS: Binary platform engine built and secured.")
        status_vector = "COMPLETED"
    elif task_action == "route_bgp":
        logs.append("INIT: Querying routing tables of peer AS65001...")
        logs.append("SUCCESS: 100% telemetry packets verified. Zero route flapping.")
        status_vector = "VERIFIED"
    elif task_action == "ebpf_bypass":
        logs.append("INIT: Loading eBPF program into kernel space...")
        logs.append("SUCCESS: Network bypass live over interface eth0.")
        status_vector = "BYPASSED"
    else:
        logs.append(f"INIT: Executing default workflow {task_action}...")
        logs.append("SUCCESS: Default routine complete.")
        status_vector = "OK"

    response = {
        "action": task_action,
        "status": status_vector,
        "logs": "\n".join(logs)
    }
    return json.dumps(response)

def _list_substrate_files():
    root_dir = "/content"
    files_structure = []
    try:
        for item in sorted(os.listdir(root_dir)):
            full_path = os.path.join(root_dir, item)
            is_dir = os.path.isdir(full_path)
            files_structure.append({
                "name": item,
                "type": "directory" if is_dir else "file",
                "size": os.path.getsize(full_path) if not is_dir else "-"
            })
    except Exception as e:
        return json.dumps([{"name": f"Error reading files: {str(e)}", "type": "error", "size": "-"}])
    return json.dumps(files_structure)

# Register the callbacks globally
try:
    output.register_callback('process_ai_prompt', _process_ai_prompt)
    output.register_callback('trigger_sovereign_task', _trigger_sovereign_task)
    output.register_callback('list_substrate_files', _list_substrate_files)
except Exception as e:
    pass

